-- run stamp '2026-10-04d_period-label-bucket'; journal test id 'period-label/residue'.
-- Every UPDATE is conditioned on the old value the plan names; every change is journalled
-- in the same transaction, so the audit trail cannot disagree with the data.
\set ON_ERROR_STOP on
BEGIN;

-- The server bounds this transaction itself: a lock wait or a runaway statement raises
-- here, psql stops the script (exit 3) and nothing is kept. A client that gives up does
-- not stop the server - psql has the whole script on its stdin.
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

CREATE TEMP TABLE _period_label_bucket_plan (
    site_id     UUID NOT NULL,
    column_name TEXT NOT NULL,
    old_value   TEXT,
    new_value   TEXT,
    change_key  TEXT NOT NULL,
    reason      TEXT NOT NULL,
    premise     TEXT NOT NULL,
    evidence    JSONB NOT NULL,
    PRIMARY KEY (site_id, column_name)
) ON COMMIT DROP;

INSERT INTO _period_label_bucket_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('21bd525e-fe10-40dd-96be-32d3c8d36d26'::uuid, 'period_name', '1 - 500 AD', '500 - 1000 AD', 'period-label-bucket-2026-10-04d:21bd525e-fe10-40dd-96be-32d3c8d36d26:period_name', 'period-label-bucket-2026-10-04d (bucket-of-period-start): period_start 850: ''1 - 500 AD'' -> ''500 - 1000 AD''', '850', '[{"source": "pipeline/utils/text.py", "url": "pipeline/utils/text.py", "quote": "categorize_period(850) = ''500 - 1000 AD''"}, {"source": "ancient-nerds-map/src/data/sites.ts", "url": "ancient-nerds-map/src/data/sites.ts", "quote": "categorizePeriod(850) = ''500 - 1000 AD''"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 1;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a curated site that still exists
    SELECT count(*) INTO bad
      FROM _period_label_bucket_plan p LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'period_name bucket: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _period_label_bucket_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'period_name' THEN p.new_value::text IS NOT DISTINCT FROM p.old_value::text OR p.new_value IS NULL OR p.old_value IS NULL OR length(p.new_value) > 100
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'period_name bucket: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _period_label_bucket_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'period_name' THEN u.period_name IS DISTINCT FROM p.old_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'period_name bucket: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 4: every planned row writes a value this lane owns (new value)
    SELECT count(*) INTO bad FROM _period_label_bucket_plan p
     WHERE CASE p.column_name
                WHEN 'period_name' THEN p.new_value NOT IN ('< 4500 BC', '4500 - 3000 BC', '3000 - 1500 BC', '1500 - 500 BC', '500 BC - 1 AD', '1 - 500 AD', '500 - 1000 AD', '1000 - 1500 AD', '1500+ AD', 'Undated')
                ELSE false END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'period_name bucket: % planned row(s) write a value this lane does not own', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _period_label_bucket_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (u.period_start::text) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'period_name bucket: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _period_label_bucket_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'unified_sites', r.column_name, 'id', r.site_id::text,
            r.old_value, r.new_value,
            'period-label/residue', '2026-10-04d_period-label-bucket', r.change_key, 'authoritative', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'period_name bucket: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _period_label_bucket_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'period_name' THEN u.period_name IS DISTINCT FROM p.new_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'period_name bucket: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _period_label_bucket_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'unified_sites'
       AND l.column_name = p.column_name
       AND l.run_stamp = '2026-10-04d_period-label-bucket'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'period_name bucket: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = '2026-10-04d_period-label-bucket'
       AND (l.table_name <> 'unified_sites' OR l.column_name NOT IN ('period_name'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'period_name bucket: this run stamp journalled % row(s) outside unified_sites.(period_name)', bad;
    END IF;

    RAISE NOTICE 'period_name bucket: % of % planned cell(s) changed and journalled over 1 curated site(s)',
        moved, expected;
END $$;

COMMIT;

